/** Notion public OAuth+PKCE client. Credentials stay in the Android Keystore vault. */
public final class NotionHub {
 private static NotionHub singleton;public static synchronized NotionHub get(Context c){if(singleton==null)singleton=new NotionHub(c);return singleton;}
 private static final String ORIGIN="https://mcp.notion.com",KEY="ara.notion.oauth";
 private final Context context;private JSONObject vault=new JSONObject();private String session="",message="";private boolean pending,initialized;private long serial;
 public NotionHub(Context c){context=c.getApplicationContext();try{AtomicFile f=new AtomicFile(new File(context.getFilesDir(),"notion-oauth.bin"));try(InputStream in=f.openRead()){byte[] data=read(in,200000);JSONObject wrapped=new JSONObject(new String(data,StandardCharsets.UTF_8));Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.DECRYPT_MODE,key(),new GCMParameterSpec(128,Base64.decode(wrapped.getString("iv"),Base64.NO_WRAP)));vault=new JSONObject(new String(cipher.doFinal(Base64.decode(wrapped.getString("data"),Base64.NO_WRAP)),StandardCharsets.UTF_8));}}catch(FileNotFoundException empty){}catch(Exception error){message="이 기기의 노션 연결을 다시 진행해 주세요.";}}
 private javax.crypto.SecretKey key()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(KEY)){KeyGenerator gen=KeyGenerator.getInstance("AES","AndroidKeyStore");gen.init(new KeyGenParameterSpec.Builder(KEY,KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());gen.generateKey();}return(javax.crypto.SecretKey)ks.getKey(KEY,null);}
 private void save()throws Exception{Cipher cipher=Cipher.getInstance("AES/GCM/NoPadding");cipher.init(Cipher.ENCRYPT_MODE,key());JSONObject wrapped=new JSONObject().put("iv",Base64.encodeToString(cipher.getIV(),Base64.NO_WRAP)).put("data",Base64.encodeToString(cipher.doFinal(vault.toString().getBytes(StandardCharsets.UTF_8)),Base64.NO_WRAP));AtomicFile f=new AtomicFile(new File(context.getFilesDir(),"notion-oauth.bin"));FileOutputStream out=null;try{out=f.startWrite();out.write(wrapped.toString().getBytes(StandardCharsets.UTF_8));f.finishWrite(out);}catch(Exception e){if(out!=null)f.failWrite(out);throw e;}}
 private static byte[] read(InputStream in,int limit)throws Exception{try(ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>limit)throw new IOException("응답이 너무 큽니다.");out.write(b,0,n);}return out.toByteArray();}}
 private static String random(){byte[] b=new byte[32];new SecureRandom().nextBytes(b);return b64(b);}
 private static String b64(byte[] b){return Base64.encodeToString(b,Base64.URL_SAFE|Base64.NO_WRAP|Base64.NO_PADDING);}
 private static String form(JSONObject o)throws Exception{StringBuilder out=new StringBuilder();Iterator<String> it=o.keys();while(it.hasNext()){String k=it.next();if(out.length()>0)out.append('&');out.append(URLEncoder.encode(k,"UTF-8")).append('=').append(URLEncoder.encode(o.getString(k),"UTF-8"));}return out.toString();}
 private JSONObject http(String path,String method,String body,String type,String token)throws Exception{if(!path.startsWith("/")||path.startsWith("//")||path.contains(".."))throw new IOException("노션 주소 오류");HttpURLConnection c=(HttpURLConnection)new URL(ORIGIN+path).openConnection(Proxy.NO_PROXY);try{c.setConnectTimeout(15000);c.setReadTimeout(45000);c.setInstanceFollowRedirects(false);c.setRequestMethod(method);c.setRequestProperty("User-Agent","ARA-Daily-OS/2.1");c.setRequestProperty("Accept","application/json, text/event-stream");if(token!=null&&!token.isEmpty())c.setRequestProperty("Authorization","Bearer "+token);if(path.equals("/mcp")){c.setRequestProperty("MCP-Protocol-Version","2025-03-26");if(!session.isEmpty())c.setRequestProperty("Mcp-Session-Id",session);}if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type",type);try(OutputStream out=c.getOutputStream()){out.write(body.getBytes(StandardCharsets.UTF_8));}}int code=c.getResponseCode();if(code<200||code>=300){String raw="";try(InputStream in=c.getErrorStream()){if(in!=null)raw=new String(read(in,65536),StandardCharsets.UTF_8);}catch(Exception ignored){}throw NotionFailure.from(path,code,raw);}if(path.equals("/mcp")&&c.getHeaderField("Mcp-Session-Id")!=null)session=c.getHeaderField("Mcp-Session-Id");String text;try(InputStream in=c.getInputStream()){text=new String(read(in,2000000),StandardCharsets.UTF_8);}return NotionResponse.parse(path,body,text);}finally{c.disconnect();}}
 private JSONObject token(JSONObject fields)throws Exception{return http("/token","POST",form(fields),"application/x-www-form-urlencoded",null);}
 private void tokens(JSONObject value)throws Exception{vault.remove("reconnectRequired");if(value.optString("access_token").length()<10)throw new IOException("노션 연결 정보를 받지 못했습니다.");Iterator<String> it=value.keys();while(it.hasNext()){String k=it.next();vault.put(k,value.get(k));}vault.put("expires_at",System.currentTimeMillis()+value.optLong("expires_in",3600)*1000);save();session="";initialized=false;}
 private String access()throws Exception{if(vault.optString("access_token").isEmpty())throw new IOException("노션 다시 연결을 눌러 주세요. 기록과 저장 위치는 유지됩니다.");if(vault.optLong("expires_at",0)<System.currentTimeMillis()+60000)try{tokens(token(new JSONObject().put("grant_type","refresh_token").put("refresh_token",vault.optString("refresh_token")).put("client_id",vault.optString("client_id"))));}catch(NotionFailure e){if(e.reconnect){message=e.getMessage();vault.put("reconnectRequired",true);save();}throw e;}return vault.getString("access_token");}
 private void initializeSession()throws Exception{session="";initialized=false;rpc("initialize",new JSONObject().put("protocolVersion","2025-03-26").put("capabilities",new JSONObject()).put("clientInfo",new JSONObject().put("name","ARA Daily OS").put("version","2.7")));http("/mcp","POST",new JSONObject().put("jsonrpc","2.0").put("method","notifications/initialized").toString(),"application/json",access());initialized=true;}
 private JSONObject rpc(String method,JSONObject args)throws Exception{return rpcAttempt(method,args,true);}
 private JSONObject rpcAttempt(String method,JSONObject args,boolean retry)throws Exception{String bearer=access();if(!method.equals("initialize")&&!initialized){initializeSession();bearer=access();}JSONObject result;try{result=http("/mcp","POST",new JSONObject().put("jsonrpc","2.0").put("id",++serial).put("method",method).put("params",args).toString(),"application/json",bearer);}catch(NotionFailure e){if(e.reconnect){message=e.getMessage();vault.put("reconnectRequired",true);save();}if(e.sessionExpired&&!method.equals("initialize")&&retry){initializeSession();return rpcAttempt(method,args,false);}throw e;}if(result.has("error"))throw new IOException("노션 요청 실패: "+result.getJSONObject("error").optString("message"));return result.getJSONObject("result");}
 static boolean allowedTool(String name){String n=name.replace('_','-');for(String suffix:new String[]{"fetch","search","get-self","get-tool-access","list-private-pages","list-shared-pages","list-recent-pages","create-pages","create-database","create-view"})if(n.equals(suffix)||n.equals("notion-"+suffix))return true;return false;}
 public synchronized JSONObject request(Activity a,JSONObject input)throws Exception{switch(input.optString("op")){
  case "status":return new JSONObject().put("connected",!vault.optString("access_token").isEmpty()).put("pending",pending).put("reconnectRequired",vault.optBoolean("reconnectRequired")).put("message",message).put("workspace",vault.optString("workspace_name")).put("target",vault.opt("target")).put("destination",vault.opt("destination"));
  case "auto-status":return new JSONObject(NotionDiarySync.status(context));
  case "auto-enable":NotionDiarySync.setEnabled(context,input.optBoolean("enabled"));return new JSONObject(NotionDiarySync.status(context));
  case "auto-sync":NotionDiarySync.retryNow(context);return new JSONObject().put("queued",true);
  case "connect":begin(a);return new JSONObject().put("pending",true);
  case "disconnect":if(pending)throw new IOException("노션 로그인 창을 먼저 완료해 주세요.");vault=new JSONObject();save();session="";return new JSONObject().put("connected",false);
  case "target":JSONObject target=input.getJSONObject("target");UUID.fromString(target.getString("id"));vault.put("target",target);save();NotionDiarySync.destinationChanged(context);return new JSONObject().put("saved",true);
  case "destination":JSONObject dest=input.getJSONObject("destination");String destId=NotionDaily.id(dest.getString("id"));JSONObject previous=vault.optJSONObject("destination"),oldTarget=vault.optJSONObject("target");if(oldTarget!=null&&!destId.equals(oldTarget.optString("parentId")))vault.remove("target");vault.put("destination",new JSONObject().put("id",destId).put("title",dest.optString("title","저장 페이지")));save();return new JSONObject().put("saved",true);
  case "daily":case "daily-reset":case "inline":case "diary":if("diary".equals(input.optString("op"))&&!NotionDiary.active(input))return new JSONObject().put("skipped",true).put("reason","no_activity");JSONObject dailyTarget=vault.optJSONObject("target");if(dailyTarget==null)throw new IOException("저장할 하루 기록 DB를 먼저 지정해 주세요.");if("inline".equals(input.optString("op"))){JSONObject result=NotionDaily.inline(dailyTarget,dailyCall(a),value->{dailyTarget.put("inlinePending",value);if(!value)dailyTarget.put("inlineParentId",dailyTarget.getString("parentId"));save();});dailyTarget.put("inlineParentId",dailyTarget.getString("parentId"));dailyTarget.put("inlinePending",false);dailyTarget.put("inlineRevision",2);save();return result;}if("diary".equals(input.optString("op"))&&!dailyTarget.optString("parentId").isEmpty()&&dailyTarget.optInt("inlineRevision")!=2)request(a,new JSONObject().put("op","inline"));String day=NotionDaily.date(input),dayKey=dailyTarget.getString("id")+"|"+day;JSONObject journal=vault.optJSONObject("dailyPending");if(journal==null){journal=new JSONObject();vault.put("dailyPending",journal);}final JSONObject savedJournal=journal;if("daily-reset".equals(input.optString("op"))){journal.remove(dayKey);save();return new JSONObject().put("reset",true);}NotionDaily.Call writer=dailyCall(a);NotionDaily.Mark marker=value->{if(value)savedJournal.put(dayKey,true);else savedJournal.remove(dayKey);save();};return "diary".equals(input.optString("op"))?NotionDiary.save(input,dailyTarget,journal.optBoolean(dayKey),writer,marker):NotionDaily.save(input,dailyTarget,journal.optBoolean(dayKey),writer,marker);
  case "tools":case "call":access();if(input.getString("op").equals("tools"))return rpc("tools/list",new JSONObject());String name=input.getString("name");if(!allowedTool(name))throw new IOException("허용하지 않는 노션 작업입니다.");if(name.replace('_','-').equals("notion-create-pages")||name.replace('_','-').equals("create-pages"))NotionPagePolicy.validate(input.getJSONObject("arguments"));return rpc("tools/call",new JSONObject().put("name",name).put("arguments",input.getJSONObject("arguments")));
  default:throw new IOException("지원하지 않는 노션 요청입니다.");}}
 private NotionDaily.Call dailyCall(Activity a)throws Exception{JSONArray tools=request(a,new JSONObject().put("op","tools")).getJSONArray("tools");return(suffix,args)->{String name="";for(int i=0;i<tools.length();i++){String candidate=tools.getJSONObject(i).getString("name"),normal=candidate.replace('_','-');if(normal.equals(suffix)||normal.equals("notion-"+suffix)){name=candidate;break;}}if(name.isEmpty())throw new IOException("현재 노션 계정에서 "+suffix+" 기능을 사용할 수 없습니다.");return rpc("tools/call",new JSONObject().put("name",name).put("arguments",args));};}
 private void begin(Activity a)throws Exception{if(pending)throw new IOException("이미 노션 로그인 창을 기다리고 있습니다.");JSONObject meta=http("/.well-known/oauth-authorization-server","GET",null,null,null);if(!meta.optString("issuer").equals(ORIGIN)||!meta.optString("registration_endpoint").equals(ORIGIN+"/register")||!meta.optString("authorization_endpoint").equals(ORIGIN+"/authorize")||!meta.optString("token_endpoint").equals(ORIGIN+"/token"))throw new IOException("노션 인증 서버 확인 실패");ServerSocket server=new ServerSocket(0,4,InetAddress.getByName("127.0.0.1"));try{String redirect="http://127.0.0.1:"+server.getLocalPort()+"/notion/callback";JSONObject reg=http("/register","POST",new JSONObject().put("client_name","ARA Daily OS").put("redirect_uris",new JSONArray().put(redirect)).put("grant_types",new JSONArray().put("authorization_code").put("refresh_token")).put("response_types",new JSONArray().put("code")).put("token_endpoint_auth_method","none").toString(),"application/json",null);String client=reg.getString("client_id"),state=random(),verifier=random(),challenge=b64(MessageDigest.getInstance("SHA-256").digest(verifier.getBytes(StandardCharsets.US_ASCII)));String url=ORIGIN+"/authorize?"+form(new JSONObject().put("response_type","code").put("client_id",client).put("redirect_uri",redirect).put("state",state).put("code_challenge",challenge).put("code_challenge_method","S256").put("scope","default"));pending=true;message="노션에서 로그인·허용 후 앱으로 돌아와 주세요.";a.runOnUiThread(()->{try{a.startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)));}catch(Exception e){synchronized(this){message="로그인 화면을 열지 못했습니다.";pending=false;}try{server.close();}catch(Exception ignored){}}});new Thread(()->callback(server,redirect,client,state,verifier),"ARA-Notion-OAuth").start();}catch(Exception e){server.close();pending=false;throw e;}}
 private void callback(ServerSocket server,String redirect,String client,String state,String verifier){long until=System.currentTimeMillis()+300000;try{server.setSoTimeout(1000);while(System.currentTimeMillis()<until){Socket socket;try{socket=server.accept();}catch(SocketTimeoutException waiting){continue;}try(Socket s=socket){s.setSoTimeout(3000);BufferedReader reader=new BufferedReader(new InputStreamReader(s.getInputStream(),StandardCharsets.US_ASCII));String line=reader.readLine();if(line==null||line.length()>8192)continue;String[] pieces=line.split(" ");if(pieces.length!=3||!pieces[0].equals("GET"))continue;Uri uri=Uri.parse("http://127.0.0.1"+pieces[1]);if(!"/notion/callback".equals(uri.getPath())||!state.equals(uri.getQueryParameter("state")))continue;String reply="노션 연결을 완료했습니다. ARA 앱으로 돌아가 주세요.";try{if(uri.getQueryParameter("error")!=null)throw new IOException("노션 연결을 취소했습니다.");String code=uri.getQueryParameter("code");if(code==null)throw new IOException("노션 로그인 코드를 받지 못했습니다.");synchronized(this){JSONObject value=token(new JSONObject().put("grant_type","authorization_code").put("client_id",client).put("redirect_uri",redirect).put("code_verifier",verifier).put("code",code));vault.put("client_id",client);if(!vault.optString("workspace_id").isEmpty()&&!value.optString("workspace_id").isEmpty()&&!vault.optString("workspace_id").equals(value.optString("workspace_id"))){vault.remove("target");vault.remove("destination");vault.remove("dailyPending");}tokens(value);message="노션 연결됨";NotionDiarySync.poke(context);}}catch(Exception error){synchronized(this){message=error.getMessage();}reply="연결을 완료하지 못했습니다. ARA 앱에서 상태를 확인해 주세요.";}byte[] body=("<!doctype html><meta charset=utf-8><title>ARA 노션 연결</title><p>"+reply+"</p>").getBytes(StandardCharsets.UTF_8);OutputStream out=s.getOutputStream();out.write(("HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=utf-8\r\nContent-Length: "+body.length+"\r\nCache-Control: no-store\r\nConnection: close\r\n\r\n").getBytes(StandardCharsets.US_ASCII));out.write(body);return;}}synchronized(this){message="로그인 대기 시간이 지났습니다. 다시 연결해 주세요.";}}catch(Exception error){synchronized(this){if(pending)message="노션 연결을 완료하지 못했습니다. 다시 연결해 주세요.";}}finally{try{server.close();}catch(Exception ignored){}synchronized(this){pending=false;}}}
}
